#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    int minRotationsToDialModM(std::vector<int>& target, int m) {
        int curr = 0;
        int total = 0;
        for (int dig : target) {
            int diff = std::abs(curr - dig);
            total += std::min(diff, m - diff);
            curr = dig;
        }
        return total;
    }
};

